for name,route in gen._main_strokes():
 for a,b in zip(route[:-1],route[1:]):
  du=b[0]-a[0];dv=b[1]-a[1];alpha=math.atan2(dv,du);theta=(a[2]+b[2])/2;beta=-theta
  diff=alpha-beta
  width_mm=math.sqrt((4*math.sin(diff))**2+(0.4*math.cos(diff))**2)
  w=max(1,int(round(width_mm/gen.MM_PER_PX)))
